-- A parenthesized join as a MERGE source; unaliased, its FROM items stay
-- visible by name in the condition, actions and RETURNING.
CREATE TABLE t214 (id int, v int); CREATE TABLE a214 (id int, n int); CREATE TABLE b214 (id int, w int);
INSERT INTO t214 VALUES (1, 0), (2, 0); INSERT INTO a214 VALUES (1, 10), (3, 30); INSERT INTO b214 VALUES (1, 5), (3, 7);
MERGE INTO t214 USING (a214 CROSS JOIN LATERAL (SELECT a214.n * 2 AS d) l) s ON t214.id = s.id
  WHEN MATCHED THEN UPDATE SET v = s.d WHEN NOT MATCHED THEN INSERT VALUES (s.id, s.d);
SELECT * FROM t214 ORDER BY id;
MERGE INTO t214 USING (a214 JOIN b214 USING (id)) ON t214.id = a214.id WHEN MATCHED THEN UPDATE SET v = a214.n + b214.w;
SELECT * FROM t214 ORDER BY id;
MERGE INTO t214 USING (a214 JOIN b214 USING (id)) j ON t214.id = j.id WHEN MATCHED THEN UPDATE SET v = j.n - j.w;
SELECT * FROM t214 ORDER BY id;
MERGE INTO t214 USING (a214 LEFT JOIN b214 ON a214.id = b214.id) ON t214.id = a214.id WHEN MATCHED THEN UPDATE SET v = coalesce(b214.w, -1) RETURNING merge_action(), t214.*, a214.n;
MERGE INTO t214 USING ((a214)) ON t214.id = a214.id WHEN MATCHED THEN DO NOTHING;
MERGE INTO t214 USING (a214 JOIN b214 ON a214.id = b214.id) j ON t214.id = a214.id WHEN MATCHED THEN DO NOTHING;
MERGE INTO t214 USING (a214 JOIN b214 USING (id)) ON t214.id = a214.id WHEN MATCHED THEN UPDATE SET v = n RETURNING *;
MERGE INTO t214 USING (a214 JOIN b214 USING (id)) ON t214.id = a214.id WHEN MATCHED THEN UPDATE SET v = 1 RETURNING a214.*, b214;
MERGE INTO t214 USING (a214 JOIN b214 ON a214.id = b214.id) ON t214.id = a214.id WHEN NOT MATCHED THEN INSERT VALUES (a214.id, b214.w) WHEN MATCHED AND b214.w > 5 THEN DELETE RETURNING merge_action(), b214.w;
MERGE INTO t214 USING (a214 JOIN b214 USING (id) AS j) ON t214.id = j.id WHEN MATCHED THEN UPDATE SET v = a214.n RETURNING j.id, t214.v;
MERGE INTO t214 USING (a214 JOIN b214 USING (id)) ON t214.id = a214.id WHEN MATCHED THEN UPDATE SET v = a214.nosuch;
DROP TABLE t214, a214, b214;
